void cmd_set_vision_llm(int argc, char** argv)
{
    if (argc < 2) {
        printf("Usage: set_vision_llm <preset> [api_key]\n"
               "       set_vision_llm <host> <model> [api_key]\n"
               "       set_vision_llm clear\n"
               "\n"
               "Set an independent vision model. If not configured,\n"
               "vision calls inherit the main LLM config.\n"
               "\n"
               "Presets:\n"
               "  mimo     - api.xiaomimimo.com  (mimo-v2-omni)\n"
               "  openai   - api.openai.com  (gpt-4o)\n"
               "  qwen     - dashscope.aliyuncs.com  (qwen-vl-max)\n"
               "  glm      - open.bigmodel.cn  (glm-4v-flash)\n"
               "\n"
               "Examples:\n"
               "  set_vision_llm mimo <api_key>\n"
               "  set_vision_llm clear\n");
        return;
    }

    const char* arg1 = argv[1];

    /* clear: remove vision-specific config, fall back to main LLM */
    if (strcmp(arg1, "clear") == 0) {
        llm_set_vision_model(NULL, NULL, NULL);
        printf("Vision LLM config cleared (using main LLM).\n");
        return;
    }
    http_proxy_clear();
    printf("Proxy cleared. Restart to apply.\n");
}

static void cmd_set_wifi(int argc, char** argv)
{
    if (argc < 3) {
        printf("Usage: set_wifi <ssid> <password>\n");
        return;
    }
    printf("Connecting to '%s' ...\n", argv[1]);
    int err = network_wifi_connect(NULL, argv[1], argv[2]);
    if (err == OK)
        printf("WiFi connected: %s\n", network_get_ip());
    else
        printf("WiFi failed. Check SSID/password or run net_status.\n");
}

static void cmd_wifi_reconnect(void)
{
    printf("Reconnecting WiFi ...\n");
    int err = network_wifi_reconnect();
    if (err == OK)
        printf("Reconnected: %s\n", network_get_ip());
    else if (err == ERROR)
        printf("No saved credentials. Use: set_wifi <ssid> <pass>\n");
    else
        printf("WiFi reconnect failed.\n");
}

