void vsyslog(int priority, FAR const IPTR char *fmt, va_list ap)
{
  FAR struct task_info_s *info = task_get_info();

  /* Check if this priority is enabled */

  if ((info && info->ta_syslog_mask & LOG_MASK(priority)) != 0)
    {
      /* Yes.. Perform the nx_vsyslog system call.
       *
       * NOTE:  The va_list parameter is passed by reference.  That is
       * because the va_list is a structure in some compilers and passing
       * of structures in the NuttX syscalls does not work.
       */

#ifdef va_copy
      va_list copy;

      va_copy(copy, ap);
      nx_vsyslog(priority, fmt, &copy);
      va_end(copy);
#else
      nx_vsyslog(priority, fmt, &ap);
#endif
    }
}

/****************************************************************************
===
 * Name: nx_syslog
 *
 * Description:
 *   nx_syslog() handles the system logging system calls. It is functionally
 *   equivalent to syslog() but is used within the kernel space.
 *
 ****************************************************************************/

void nx_syslog(int priority, FAR const IPTR char *fmt, ...)
{
  va_list ap;

  if ((g_syslog_mask & LOG_MASK(priority)) != 0)
    {
      /* Let nx_vsyslog do all of the work */

      va_start(ap, fmt);
      nx_vsyslog(priority, fmt, &ap);
      va_end(ap);
    }
