```c
#include "cJSON.h"

#define WIFI_NETDIR "/data/etc/wifi/networks.d"
#define WIFI_FALLBACK_CONF "/data/etc/wifi/wapi.conf"

/* Read {"ssid":"...","psk":"..."} from a config file.
 * Returns 0 on success. */
static int wifi_read_conf(const char* path, char* ssid, size_t ssid_size,
                          char* psk, size_t psk_size)
{
    FILE* fp = fopen(path, "r");
    if (!fp) return -ENOENT;
    char buf[512];
    size_t n = fread(buf, 1, sizeof(buf) - 1, fp);
    fclose(fp);
    if (n == 0) return -EINVAL;
    buf[n] = '\0';

    cJSON* root = cJSON_Parse(buf);
    if (!root) return -EINVAL;

    const cJSON* jssid = cJSON_GetObjectItemCaseSensitive(root, "ssid");
    if (!cJSON_IsString(jssid) || !jssid->valuestring[0]) {
        cJSON_Delete(root);
        return -EINVAL;
    }
    strlcpy(ssid, jssid->valuestring, ssid_size);

    psk[0] = '\0';
    const cJSON* jpsk = cJSON_GetObjectItemCaseSensitive(root, "psk");
    if (cJSON_IsString(jpsk)) {
        strlcpy(psk, jpsk->valuestring, psk_size);
    }

    cJSON_Delete(root);
    return OK;
}
```

