static int wifi_read_conf(const char* path, char* ssid, size_t ssid_size,
                          char* psk, size_t psk_size)
{
    char buf[512];
    FILE* fp = fopen(path, "r");
    size_t n;

    if (!fp) return ERROR;
    n = fread(buf, 1, sizeof(buf) - 1, fp);
    fclose(fp);
    if (n == 0) return ERROR;
    buf[n] = '\0';

    cJSON* root = cJSON_Parse(buf);
    if (!root) {
        syslog(LOG_WARNING, "[%s] bad wifi conf: %s\n", TAG, path);
        return ERROR;
    }

    const cJSON* jssid = cJSON_GetObjectItemCaseSensitive(root, "ssid");
    int ret = ERROR;
    if (cJSON_IsString(jssid) && jssid->valuestring[0]) {
        snprintf(ssid, ssid_size, "%s", jssid->valuestring);
        psk[0] = '\0';
        const cJSON* jpsk = cJSON_GetObjectItemCaseSensitive(root, "psk");
        if (cJSON_IsString(jpsk)) {
            snprintf(psk, psk_size, "%s", jpsk->valuestring);
        }
        ret = OK;
    }
    cJSON_Delete(root);
    return ret;
}

