    }

    size_t n = fread(buf, 1, sizeof(buf) - 1, fp);
    fclose(fp);
    if (n == 0) {
        return ERROR;
    }
    buf[n] = '\0';

    cJSON* root = cJSON_Parse(buf);
    if (!root) {
        syslog(LOG_WARNING, "[%s] bad WiFi conf: %s\n", TAG, path);
        return ERROR;
    }

    int ret = ERROR;
    const cJSON* jssid = cJSON_GetObjectItemCaseSensitive(root, "ssid");
    if (cJSON_IsString(jssid) && jssid->valuestring[0]) {
